from __future__ import annotations
import ast, base64, py_compile, shutil, sys, tempfile
from datetime import datetime
from pathlib import Path
ROOT=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path.cwd().resolve()
STAMP=datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP=ROOT/f"backup_modulo_cadastros_{STAMP}"
FILES={
    'app/models.py': base64.b64decode(''),
    'app/access_control.py': base64.b64decode(''),
    'app/templates/base.html': base64.b64decode(''),
    'app/templates/portal_employees.html': base64.b64decode(''),
    'app/static/styles.css': base64.b64decode(''),
    'app/static/portal.css': base64.b64decode(''),
    'app/templates/cadastros.html': base64.b64decode(''),
    'app/templates/departments.html': base64.b64decode(''),
    'app/templates/department_detail.html': base64.b64decode(''),
    'app/templates/systems.html': base64.b64decode(''),
}
EMPLOYEE_FUNCTION="@router.get('/portal/funcionarios', response_class=HTMLResponse)\ndef portal_employees(\n    request: Request,\n    session: Db,\n    user: Annotated[SystemUser, Depends(require_user)],\n    nome: str = '',\n    departamento_id: int | None = None,\n    cargo_id: int | None = None,\n    situacao: str = 'TODOS',\n):\n    nome=nome.strip(); ti_manager=user.role in {ROLE_ADMIN,ROLE_ANALYST}\n    query=scoped_employee_query(user)\n    if nome:\n        term=f'%{nome}%'; query=query.where((Funcionario.nome.ilike(term)) | (Funcionario.login.ilike(term)))\n    if ti_manager and departamento_id: query=query.where(Funcionario.departamento_id==departamento_id)\n    if cargo_id: query=query.join(FuncionarioCargo,FuncionarioCargo.funcionario_id==Funcionario.id).where(FuncionarioCargo.cargo_id==cargo_id)\n    if situacao=='ATIVO': query=query.where(Funcionario.ativo.is_(True))\n    elif situacao=='INATIVO': query=query.where(Funcionario.ativo.is_(False))\n    employees=session.scalars(query).unique().all()\n    employee_rows=[]\n    for employee in employees:\n        cargos=session.scalars(select(Cargo.nome).join(FuncionarioCargo,FuncionarioCargo.cargo_id==Cargo.id).where(FuncionarioCargo.funcionario_id==employee.id).order_by(Cargo.nome)).all()\n        employee_rows.append({'employee':employee,'cargos':list(cargos)})\n    departments=session.scalars(select(Departamento).order_by(Departamento.nome)).all() if ti_manager else []\n    cargo_query=select(Cargo).where(Cargo.ativo.is_(True)).order_by(Cargo.nome)\n    selected_department=departamento_id if ti_manager else user.department_id\n    if selected_department: cargo_query=cargo_query.where(Cargo.departamento_id==selected_department)\n    cargos=session.scalars(cargo_query).all()\n    return templates.TemplateResponse(request=request,name='portal_employees.html',context={'user':user,'employee_rows':employee_rows,'employees':employees,'departments':departments,'cargos':cargos,'filter_name':nome,'filter_department_id':departamento_id,'filter_cargo_id':cargo_id,'filter_status':situacao,'show_department_filter':ti_manager})\n"

def replace_function(source,name,replacement):
    tree=ast.parse(source); node=next((x for x in tree.body if isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef)) and x.name==name),None)
    if node is None or node.end_lineno is None: raise RuntimeError(f"Funcao {name} nao encontrada")
    lines=source.splitlines(keepends=True); start=sum(map(len,lines[:node.lineno-1])); end=sum(map(len,lines[:node.end_lineno]))
    # Inclui os decorators imediatamente anteriores.
    if node.decorator_list:
        ds=min(x.lineno for x in node.decorator_list); start=sum(map(len,lines[:ds-1]))
    return source[:start]+replacement.rstrip()+"\n\n"+source[end:].lstrip("\n")

required=[ROOT/'app/models.py',ROOT/'app/access_control.py',ROOT/'app/templates/base.html',ROOT/'app/templates/portal_employees.html',ROOT/'app/static/styles.css',ROOT/'app/static/portal.css']
missing=[str(x) for x in required if not x.exists()]
if missing: raise RuntimeError('Arquivos ausentes: '+', '.join(missing))
for path in required:
    dest=BACKUP/path.relative_to(ROOT);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(path,dest)
# Novos arquivos nao existentes sao registrados para remocao em rollback.
created=[]
try:
    for rel,data in FILES.items():
        path=ROOT/rel
        if rel=='app/access_control.py':
            text=data.decode('utf-8'); text=replace_function(text,'portal_employees',EMPLOYEE_FUNCTION); data=text.encode()
        if not path.exists(): created.append(path)
        path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
    py_compile.compile(str(ROOT/'app/models.py'),doraise=True)
    py_compile.compile(str(ROOT/'app/access_control.py'),doraise=True)
except Exception:
    for path in required:
        saved=BACKUP/path.relative_to(ROOT)
        if saved.exists(): shutil.copy2(saved,path)
    for path in created: path.unlink(missing_ok=True)
    raise
print("\n[SUCESSO] Modulo Cadastros instalado.")
print("[OK] Menu Contas alterado para Cadastros.")
print("[OK] Departamentos, cargos, sistemas e vinculos habilitados.")
print("[OK] Arvore Departamento > Cargo > Sistemas/Observacoes/Usuarios criada.")
print("[OK] Usuarios exibem departamento, cargo e filtros combinados.")
print(f"[BACKUP] {BACKUP}")
print("\nReinicie o servidor. Base.metadata.create_all criara as novas tabelas na inicializacao.")
